"""Présentation HTML commune, autonome et sans ressource distante."""
import html


def e(value):
    return html.escape(str(value), quote=True)


def styles():
    return '''<style>
:root{--ink:#172b44;--muted:#52657b;--line:#dce5ee;--accent:#126784}body{background:#f3f6fa;color:var(--ink);font:15px/1.65 system-ui,-apple-system,sans-serif;margin:0}*{box-sizing:border-box}main{max-width:1320px;margin:auto;padding:28px 32px}header{background:#fff;color:var(--ink);border:1px solid var(--line);border-top:5px solid var(--accent);border-radius:16px;padding:28px 32px;box-shadow:0 4px 18px #16345008}header h1{font-size:clamp(24px,3vw,36px);line-height:1.25;letter-spacing:-.025em;margin:10px 0}header p{color:var(--muted);margin:8px 0;overflow-wrap:anywhere}.tag,.eyebrow{font-size:11px;letter-spacing:.09em;text-transform:uppercase;font-weight:750;color:var(--accent)}h2{font-size:25px;letter-spacing:-.02em;margin:32px 0 16px}h3{font-size:19px;margin:18px 0 12px}h4{font-size:16px;margin:0 0 12px}a{color:#105d81;text-underline-offset:3px}.report-actions,.page-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:18px 0}.action{display:inline-flex;align-items:center;justify-content:center;gap:8px;text-decoration:none;background:white;border:1px solid #c6d5e1;border-radius:8px;color:#244765;padding:10px 16px;font:600 14px/1.3 system-ui;cursor:pointer;max-width:100%}.action:hover{background:#eaf2f7;border-color:#648ca7}.action.primary,.action[aria-pressed="true"]{background:#126784;border-color:#126784;color:white}.report-actions .export-actions{display:flex;gap:8px;flex-wrap:wrap;margin-left:auto}nav{padding:12px 16px;background:#e9eff5;border-radius:10px;gap:6px;margin:18px 0}nav a{border:0;background:transparent;padding:7px 10px;font-size:13px}nav a:hover{background:white}section{scroll-margin-top:18px}.panel,.finding,.exec-card{background:white;border:1px solid var(--line);border-radius:12px;padding:24px;margin:16px 0;box-shadow:0 2px 8px #16345004}.metrics,.exec-metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px;margin:16px 0}.metric,.exec-metric{background:white;padding:18px;border:1px solid var(--line);border-radius:10px}.metric strong,.exec-metric strong{display:block;font-size:32px;line-height:1.2;letter-spacing:-.03em}.exec-metric span{display:block;font-size:13px;color:var(--muted);margin-top:8px}.banner,.exec-notice{border:1px solid #eddbaf;border-left:4px solid #b87713;background:#fff8e9;padding:18px 22px;border-radius:10px;margin:18px 0}.exec-notice p{margin:8px 0}.exec-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:16px}.exec-grid .exec-card{margin:0}.exec-card .small,.small{font-size:13px;color:var(--muted)}.exec-card p,small{overflow-wrap:anywhere}.pill{display:inline-block;border-radius:5px;font-size:12px;font-weight:700;padding:4px 8px;background:#e8f1f6;color:#1f5573}.pill.warning{background:#fff0cd;color:#82500b}.exec-timeline{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:18px 0}.exec-step{background:#edf3f8;border-radius:10px;padding:18px}.exec-step b{display:block;color:#185775;margin-bottom:8px}.table{overflow:auto;border:1px solid var(--line);border-radius:10px;margin:14px 0;background:white}table{border-collapse:collapse;width:100%;min-width:700px}th,td{text-align:left;vertical-align:top;padding:12px;border-bottom:1px solid var(--line);overflow-wrap:anywhere}th{background:#edf3f8;font-size:12px;font-weight:750;letter-spacing:.025em}td{font-size:13px}tbody tr:nth-child(even){background:#fafcfe}tbody tr:hover{background:#f0f6fa}#control-matrix .table,#evidence-index .table{max-height:650px}#control-matrix th,#evidence-index th{position:sticky;top:0;z-index:1}.finding{border-left:4px solid #548ba9}.finding.high{border-left-color:#b34444}dt{font-size:13px;font-weight:750;color:#244e69}dd{font-size:14px;margin:5px 0 14px;white-space:pre-wrap;overflow-wrap:anywhere}pre{font-size:12px;background:#f2f5f9;border:1px solid var(--line);border-radius:8px;padding:16px;white-space:pre-wrap;overflow-wrap:anywhere}details{padding:4px 0}summary{cursor:pointer;font-weight:650}button,input,select{font:inherit}input,select{border:1px solid #bdcedb;border-radius:7px;padding:9px;max-width:100%}input:focus,select:focus,button:focus,a:focus{outline:3px solid #187da6;outline-offset:3px}[hidden]{display:none!important}body.executive-view main>section:not(#direction-report),body.executive-view main>nav{display:none}body.executive-view #direction-report{display:block}footer{padding:28px 0;color:var(--muted);font-size:13px}.exec-body ul{padding-left:22px}.exec-body li{margin:8px 0}
@media(max-width:650px){main{padding:16px 12px}header{padding:22px 20px}.report-actions{gap:8px}.report-actions>.action{flex:1}.report-actions .export-actions{margin:0;width:100%}.export-actions .action{flex:1;padding:10px 12px}.exec-metrics,.metrics{grid-template-columns:repeat(2,1fr)}.exec-timeline{grid-template-columns:1fr}.panel,.finding,.exec-card{padding:18px}nav{padding:8px}.exec-card h3{font-size:18px}}@media print{body{background:white}main{padding:0;max-width:none}.report-actions,.page-actions,nav,.audience-switch,.filters,#export-plan,#plan-dirty{display:none!important}.table{max-height:none!important;overflow:visible}table{min-width:0}th,td{font-size:9px;padding:5px}th{position:static!important}.exec-card,.exec-step,.finding{break-inside:avoid;box-shadow:none}.exec-grid,.exec-timeline{display:block}.exec-step{margin:12px 0}body.executive-view main>section:not(#direction-report){display:none!important}body:not(.executive-view) #direction-report{display:none!important}a{color:inherit}}
</style>'''


def executive_body(report):
    meta=report['metadata'];a=report['intelligence'];summary=report['summary']
    partial=bool(report.get('analysis_obstacles')) or 'incomplet' in report.get('status','').lower()
    is_router=report.get('asset_profile',{}).get('kind')=='routeur'
    state='Couverture partielle — compléter les preuves' if partial else 'Collecte terminée — périmètre limité'
    nature=('un audit LAN borné de la passerelle, non authentifié et sans modification' if is_router else 'un audit externe, public et non authentifié')
    text='<div class="exec-body"><div class="eyebrow">Document de décision · validation humaine requise</div><h2>Synthèse de sécurité — Direction</h2><div class="exec-notice"><b>'+e(state)+'</b><p>Ce rapport décrit '+e(nature)+'. Les impacts métier et le risque résiduel restent à valider.</p></div><div class="exec-metrics">'
    for value,label in [(summary['finding_count'],'Constats enregistrés'),(sum(summary['severity_counts'].get(s,0) for s in ('Critique','Haute')),'Constats hauts / critiques'),(summary['obstacle_count'],'Obstacles à la couverture'),(a['control_counts'].get('inconnu',0),'Contrôles sans preuve')]:
        text+='<div class="exec-metric"><strong>'+str(value)+'</strong><span>'+label+'</span></div>'
    text+='</div><h3>Décisions attendues</h3><p class="small">Les responsables, fenêtres et mesures ci-dessous sont proposés. Aucune correction ni acceptation de risque n’a été effectuée par le scanner.</p><div class="exec-grid">'
    for d in a['decisions']:
        text+='<article class="exec-card"><span class="pill">À valider</span><h3>'+e(d['title'])+'</h3><p>'+e(d['action'])+'</p><p class="small"><b>Preuve / justification :</b> '+e(d['reason'])+'</p><p class="small"><b>Responsable proposé :</b> '+e(d['owner'])+'</p><a href="report.html#constats" data-report-view="technical">Consulter les constats et preuves →</a></article>'
    if not a['decisions']:
        text+='<article class="exec-card"><h3>Compléter la qualification</h3><p>Aucun constat dans l’échantillon ne permet de conclure à l’absence de vulnérabilité. Confirmer le périmètre et obtenir les preuves internes.</p></article>'
    text+='</div><h3>Prochaines étapes proposées</h3><div class="exec-timeline">'+''.join('<div class="exec-step"><b>'+e(c['window'])+'</b>'+e(c['action'])+'</div>' for c in a['campaigns'])+'</div>'
    text+='<div class="exec-grid"><article class="exec-card"><h3>Ce qui limite la décision</h3><ul>'
    limits=[o['cause']+' — '+o['action'] for o in report.get('analysis_obstacles',[])]+a['gaps']
    text+=''.join('<li>'+e(x)+'</li>' for x in limits or ['Les parcours authentifiés et les preuves internes ne sont pas couverts par cette collecte.'])+'</ul></article>'
    context=report.get('business_context',{})
    text+='<article class="exec-card"><h3>Contexte métier</h3><p><b>Organisation :</b> '+e(meta['organization'])+'</p><p><b>Propriétaire métier :</b> '+e(context.get('owner','À désigner'))+'</p><p><b>Criticité :</b> '+e(context.get('criticality','À qualifier'))+'</p><p><b>Données :</b> '+e(context.get('data_sensitivity','À qualifier'))+'</p><p class="small">Aucun coût de perte, probabilité ou score de sécurité n’est déduit de ce scan.</p></article></div>'
    text+='<div class="exec-card"><h3>Preuves internes à demander</h3><ul>'+''.join('<li><b>'+e(x['domain'])+'</b> — '+e(x['proof'])+'<br><span class="small">'+e(x['owner'])+' · '+e(x['state'])+'</span></li>' for x in a['internal_evidence'])+'</ul><p class="small">Mesures collectées le '+e(report.get('started_utc','non renseigné'))+' · '+e(a['assurance'])+'</p></div></div>'
    return text


def executive_page(report):
    m=report['metadata']
    return '<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Synthèse de sécurité — Direction — '+e(m['organization'])+'</title>'+styles()+'</head><body><main><header><div class="tag">'+e(m['classification'])+' · '+e(m['validation'])+'</div><h1>Rapport direction</h1><p>'+e(m['organization'])+' · '+e(report['target'])+'</p></header><div class="page-actions"><a class="action primary" href="report.html">Rapport technique</a><a class="action" href="report.pdf" download>Rapport PDF</a><a class="action" href="risk-register.csv" download>Registre CSV</a></div>'+executive_body(report)+'<footer>Version '+e(m['version'])+' · Responsable : '+e(m['owner'])+' · Source : collecte '+e(report.get('started_utc',''))+'</footer></main></body></html>'


def report_actions():
    return '''<div class="report-actions" aria-label="Vues et téléchargements"><button class="action" type="button" data-report-view="technical" aria-pressed="true">Rapport technique</button><button class="action" type="button" data-report-view="direction" aria-pressed="false">Rapport direction</button><div class="export-actions"><a class="action" href="report.pdf" download>Rapport PDF</a><a class="action" href="risk-register.csv" download>Registre CSV</a><a class="action" href="executive.html" download>Direction HTML</a><a class="action" href="manifest.sha256" download>Intégrité</a></div></div>'''


def navigation_script():
    return '''<script>
const reportHeading=document.querySelector('main>header h1');const technicalHeading=reportHeading.textContent;
function hashTarget(hash){try{return document.getElementById(decodeURIComponent(hash.slice(1)));}catch{return null;}}
function selectReportView(view){const direction=view==='direction';document.body.classList.toggle('executive-view',direction);document.body.classList.remove('direction');reportHeading.textContent=direction?'Rapport direction — RSSI / CISO':technicalHeading;const pane=document.getElementById('direction-report');pane.hidden=!direction;const audience=document.getElementById('audience');if(audience)audience.value='full';document.querySelectorAll('button[data-report-view]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.reportView===view)));}
document.addEventListener('click',event=>{const control=event.target.closest('[data-report-view]');if(control){event.preventDefault();selectReportView(control.dataset.reportView);const fragment=control.hash|| (control.dataset.reportView==='direction'?'#direction-report':'#synthese');location.hash=fragment;hashTarget(fragment)?.scrollIntoView();return;}const anchor=event.target.closest('a[href^="#"]');if(anchor&&anchor.hash&&hashTarget(anchor.hash)){selectReportView(anchor.hash==='#direction-report'?'direction':'technical');}});
if(location.hash==='#direction-report')selectReportView('direction');
window.addEventListener('hashchange',()=>{if(location.hash==='#direction-report')selectReportView('direction');else if(location.hash&&hashTarget(location.hash))selectReportView('technical');});
document.addEventListener('keydown',event=>{if(event.key==='/'&&!event.ctrlKey&&!event.metaKey&&!event.altKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){selectReportView('technical');document.getElementById('risk-search')?.focus();}});
</script>'''
